#!/bin/sh
#
# Generated by the sh backend. Non-POSIX constructs used:
# - 'local': variable scoping (POSIX sh lacks local, but dash/bash/zsh support it)
# - Array emulation (name_0, name_len): arrays are not POSIX
# - '(( ))' arithmetic: required for integer comparison in conditions
# - 'grep -P' helper: PCRE not in POSIX, checked at runtime
#

# whole-array expansion helpers (the per-element vars + len counter)
_arr_expand() {
    _i=0
    _n=$(eval echo "\${$1_len}")
    _n=${_n:-0}
    while [ "$_i" -lt "$_n" ]; do
        eval "printf '%s' \"\${$1_$_i}\""
        [ "$_i" -lt "$((_n - 1))" ] && printf ' '
        _i=$((_i + 1))
    done
    printf '\n'
}
_arr_keys() {
    _i=0
    _n=$(eval echo "\${$1_len}")
    _n=${_n:-0}
    while [ "$_i" -lt "$_n" ]; do
        printf '%s\n' "$_i"
        _i=$((_i + 1))
    done
}
_arr_expand_k() {
    # assoc variant: values in key-list order ($1_keys). Joins with the
    # FIRST char of the caller's IFS (bash's ${arr[*]} semantics — under
    # IFS=newline each value lands on its own line); the key list itself
    # is space-separated, so the split runs under a fixed IFS. All in a
    # subshell: the caller's IFS is untouched.
    ( # the first IFS char (${IFS#?} = IFS minus the first char); a
      # cmdsub would eat a newline separator, so use pure expansion
      _sep=${IFS%${IFS#?}}
      IFS=' '
      _n=0
      for _k in $(eval echo "\${$1_keys}"); do
          [ "$_n" -gt 0 ] && printf '%s' "$_sep"
          eval "printf '%s' \"\${$1_$_k}\""
          _n=$((_n + 1))
      done
      printf '\n' )
}
_arr_keys_k() {
    # assoc variant: the key list
    ( IFS=' '
      for _k in $(eval echo "\${$1_keys}"); do
          printf '%s\n' "$_k"
      done )
}
_arr_slice() {
    # $1=name $2=off $3=len — elements off..off+len-1, space-joined
    _i=$(( $2 ))
    _end=$(eval echo "\${$1_len}")
    _end=${_end:-0}
    _lim=$(( $2 + ${3:-1000000} ))
    while [ "$_i" -lt "$_lim" ] && [ "$_i" -lt "$_end" ]; do
        eval "printf '%s' \"\${$1_$_i}\""
        _i=$((_i + 1))
        [ "$_i" -lt "$_lim" ] && [ "$_i" -lt "$_end" ] && printf ' '
    done
    printf '\n'
}

echo 'Testing complex array operations...'
array_0=item1; array_1=item2; array_2=item3; array_len=3
eval "array_${array_len}=\"item4\""; array_len=$((array_len + 1))
printf '%s\n' "Array: $(_arr_expand array)"
printf '%s\n' "Length: ${array_len}"
printf '%s\n' "First item: "${array_0}""
